# nicht erfunden, die Felder bleiben leer („Umrechnung unbekannt“). Rückwärts geht nichts verloren.
def expenses_in_trip_currency(apps, schema_editor):
    TripExpense = apps.get_model('reisen', 'TripExpense')
    for expense in TripExpense.objects.select_related('trip').iterator():
        expense.currency = expense.trip.currency
        expense.amount_trip = expense.amount
        expense.rate_to_trip = 1
        expense.save(update_fields=['currency', 'amount_trip', 'rate_to_trip'])


